```
if (!reducedMotion && race.shakeTimer > 0) {
  race.shakeTimer = Math.max(0, race.shakeTimer - dt);
  const k = race.shakeTimer / race.shakeDur;              // linear decay
  const e = k * k * race.shakeAmp;                        // quadratic so it lands hard and settles
  const t = race.raceTime * 46;
  engine.camera.position.x += Math.sin(t * 1.7) * e * 0.9;
  engine.camera.position.y += Math.sin(t * 2.3) * e * 0.55;
  engine.camera.rotation.z += Math.sin(t * 3.1) * e * 0.018;
  if (race.shakeTimer <= 0) race.shakeAmp = 0;
}
```
